#version 300 es
precision highp float;

// VisualSynth uniforms
uniform float uTime;
uniform float uFrame;
uniform float uFps;
uniform float uRms;

// Audio uniforms
uniform float audioLow;      // bass
uniform float audioLowSmooth; // bass_att
uniform float audioMid;      // mid
uniform float audioMidSmooth; // mid_att
uniform float audioHigh;     // treb
uniform float audioHighSmooth; // treb_att

// Screen uniforms
uniform float uAspectX;
uniform float uAspectY;
uniform vec2 uAspect;
uniform vec2 uTexSize;

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;

// Input from vertex shader
in vec2 vUv;
in vec2 vUvOriginal;
in float vRadius;
in float vAngle;

// Output
out vec4 fragColor;

// Textures
uniform sampler2D sampler_main;
uniform sampler2D sampler_noise_lq;
uniform sampler2D sampler_noise_mq;
uniform sampler2D sampler_noise_hq;
uniform sampler2D sampler_blur1;
uniform sampler2D sampler_blur2;
uniform sampler2D sampler_blur3;

// Helper functions
float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

// Texture helper functions
vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }

void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  sampler sampler_seaweed;
//vec2 uv1 = uv-.5;

vec3 ret1 = texture(sampler_main, uv) +texture(sampler_main, 1-uv)*0;


vec2 uv1 = uv*1. + uTime*0.; //0.3;
vec2 dz = vec2(0.05, 0.37);
uv1 = .25*cos(uv1 + 4.96 + uTime*.5) -2.*dz;;
vec3 dots = 0.1 + clamp(0., 1., .03/length(uv1) ) ;

ret1 = (-ret1/5.) + 6.*dots*(-0.08+ret1);
ret = ret1*5;

vec2 texc = 0.4 + 0.6*ret.xy;

vec3 col = vec3(2.2,1.2,1.3 + 0.3*sin(uTime));


vec3 ret3;
vec3 ret4;
vec3 aa = texture(sampler_seaweed, texc);

aa.x *= col.x;
aa.y *= col.y;
aa.z *= col.z;
aa.xyz -= 0.45;
//aa.x += q1;
//aa.y += q2;
//aa.z += q3;

ret3 = ret * aa * GetBlur3(uv)*10;

aa = texture(sampler_seaweed, texc);
aa.x *= col.z;
aa.y *= col.x;
aa.z *= col.y;
aa.x -= 0.95;
aa.y += 0.1;
aa.z += 3.7;
ret4 = ret * aa * GetBlur3(uv)*20;
ret4 *= 0.03;

ret = mix(ret3, ret4, (q1 + q2 + q3)*0.7);
//ret = ret4;
//ret = ret3;

//ret = ret3;
//ret = ret3;
  fragColor = ret;
}
